//! Game-state-machine parity test.
//!
//! Replays `tests/fixtures/game.log` - a sanitized excerpt of a real MTGA `Player.log`
//! containing one complete Traditional_Ladder game - and asserts the recorded submissions
//! byte-match `tests/fixtures/expected/game.jsonl`. The expected file was generated by the
//! current (oracle-validated) implementation, pinning the `add_game` payload - envelope,
//! result fields, deck lists, and the full 198-event game history - as the wire contract.
//!
//! Each expected line is `{"endpoint": ..., "use_gzip": ..., "payload": ...}` with the full
//! payload (envelope included), stored as the exact Python `json.dumps` bytes. The actual
//! submission is wrapped the same way and formatted with `to_python_json_string`, then
//! compared against the **raw expected line** - so the formatter (separators, escaping,
//! number rendering) is inside the net, not just the parsed values. One exception: the
//! envelope's `utc_time` is derived via the local timezone (mirroring Python
//! `datetime.fromtimestamp`), so it is asserted by presence/position/shape only and
//! replaced with `null` on both sides before the byte comparison. `time` comes from the
//! naive log-line timestamp and is byte-exact. (Verified: replaying under TZ=UTC /
//! America/New_York / Europe/Lisbon differs only in `utc_time`.)

use serde_json::{Map, Value};

use recall_core::follower::Follower;
use recall_core::services::seventeenlands::SeventeenLands;
use recall_core::services::seventeenlands::{
    RecordedCall, RecordingSubmitter, to_python_json_string,
};

const TOKEN: &str = "00000000-0000-4000-8000-000000000000";
const ENVELOPE_KEYS: &[&str] = &[
    "token",
    "client_version",
    "player_id",
    "time",
    "utc_time",
    "event_time",
    "raw_time",
];

fn run(fixture: &str) -> Vec<RecordedCall> {
    let data = std::fs::read_to_string(fixture).expect("read fixture");
    let mut f = Follower::with_sink(SeventeenLands::new(TOKEN.into(), RecordingSubmitter::new()));
    f.process_str(&data);
    f.sink.wire.calls
}

/// Assert `utc_time` is present at its envelope position and shaped like an ISO datetime,
/// then blank it (in place, preserving key order) so the byte comparison is
/// timezone-independent.
fn neutralize_utc_time(payload: &mut Value, ctx: &str) {
    let obj = payload.as_object_mut().expect("object payload");
    let head: Vec<&str> = obj
        .keys()
        .take(ENVELOPE_KEYS.len())
        .map(|s| s.as_str())
        .collect();
    assert_eq!(head, ENVELOPE_KEYS, "envelope key order at {ctx}");
    let utc = obj.get_mut("utc_time").unwrap();
    assert!(
        utc.as_str().map(|s| s.contains('T')).unwrap_or(false),
        "utc_time shape at {ctx}",
    );
    *utc = Value::Null;
}

#[test]
fn game_parity() {
    let calls = run("tests/fixtures/game.log");

    let raw =
        std::fs::read_to_string("tests/fixtures/expected/game.jsonl").expect("read expected jsonl");
    let expected: Vec<(&str, Value)> = raw
        .lines()
        .map(|l| (l, serde_json::from_str(l).expect("parse expected line")))
        .collect();

    assert_eq!(calls.len(), expected.len(), "submission count");

    for (i, (call, (raw_line, exp))) in calls.iter().zip(&expected).enumerate() {
        let endpoint = exp["endpoint"].as_str().unwrap();
        assert_eq!(call.endpoint, endpoint, "endpoint at [{i}]");
        assert_eq!(
            call.use_gzip,
            exp["use_gzip"].as_bool().unwrap(),
            "use_gzip at [{i}] ({endpoint})",
        );

        // Actual side: wrap like the fixture, neutralize utc_time, format as python-JSON.
        let mut actual_payload = call.payload.clone();
        neutralize_utc_time(&mut actual_payload, &format!("[{i}] ({endpoint}) actual"));
        let mut wrapper = Map::new();
        wrapper.insert("endpoint".into(), Value::String(call.endpoint.clone()));
        wrapper.insert("use_gzip".into(), Value::Bool(call.use_gzip));
        wrapper.insert("payload".into(), actual_payload);
        let actual_line = to_python_json_string(&Value::Object(wrapper));

        // Expected side: the raw bytes, with only the utc_time value swapped for null.
        // (The value is checked for shape via the parsed form; the substitution is textual
        // so everything else stays exactly as stored.)
        let mut expected_payload = exp["payload"].clone();
        neutralize_utc_time(
            &mut expected_payload,
            &format!("[{i}] ({endpoint}) expected"),
        );
        let utc = exp["payload"]["utc_time"].as_str().unwrap();
        let needle = format!("\"utc_time\": \"{utc}\"");
        assert!(
            raw_line.contains(&needle),
            "utc_time literal at [{i}] ({endpoint})"
        );
        let expected_line = raw_line.replacen(&needle, "\"utc_time\": null", 1);

        // Full-line byte comparison (key order + separators + escaping + values).
        assert_eq!(actual_line, expected_line, "payload at [{i}] ({endpoint})");
    }
}
